#!/usr/bin/env node
/**
 * Academy LMS - Multi-branch curriculum builder
 *
 * Reads the compact syllabus sources in scripts/curriculum/*.txt and the branch
 * plan in scripts/curriculum/plan.js, then:
 *   1. writes js/data_<courseId>.js (rich topic pages + auto-generated MCQs) for every new subject
 *   2. rewrites the generated block at the end of js/data.js so the new subjects,
 *      the branch catalogue (window.BRANCHES) and the branch/semester plan (window.branchPlan)
 *      are available on every page that already loads data.js.
 *
 * Source format (one subject per "@" header):
 *   @ <id> | <primary code> | <title> | <one-line description>
 *   # <unit title>
 *   - <topic title> | <overview sentence> | <Term> = <definition> | <Term> = <definition> | ...
 *
 * Run: node scripts/build_multibranch_curriculum.js
 */
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const SRC_DIR = path.join(__dirname, 'curriculum');
const JS_DIR = path.join(ROOT, 'js');
const DATA_FILE = path.join(JS_DIR, 'data.js');
const START_MARK = '// <<MULTIBRANCH:START>> (generated by scripts/build_multibranch_curriculum.js - do not edit by hand)';
const END_MARK = '// <<MULTIBRANCH:END>>';

const { BRANCHES, PLAN } = require('./curriculum/plan.js');
const REFERENCES = require('./curriculum/references.js');
const RGPV_PORTAL = 'https://www.rgpv.ac.in';

function resourcePaths(courseId) {
    const base = `assets/resources/${courseId}`;
    return {
        notesPdf: `${base}/notes/${courseId}-unit-wise-study-notes.pdf`,
        notesMd: `${base}/notes/${courseId}-unit-wise-study-notes.md`,
        paperPdf: `${base}/mock-papers/${courseId}-rgpv-model-question-paper.pdf`,
        paperMd: `${base}/mock-papers/${courseId}-rgpv-model-question-paper.md`,
        bankMd: `${base}/mock-papers/${courseId}-question-bank-with-answers.md`
    };
}

function ytSearch(query) {
    return `https://www.youtube.com/results?search_query=${encodeURIComponent(query)}`;
}

function joinList(items) {
    if (items.length <= 1) return items.join('');
    return `${items.slice(0, -1).join(', ')} and ${items[items.length - 1]}`;
}

// ---------------------------------------------------------------- parsing
function parseSources() {
    const files = fs.readdirSync(SRC_DIR).filter((f) => f.endsWith('.txt')).sort();
    const courses = [];
    let course = null;
    let unit = null;
    files.forEach((file) => {
        const lines = fs.readFileSync(path.join(SRC_DIR, file), 'utf8').split(/\r?\n/);
        lines.forEach((raw, lineNo) => {
            const line = raw.trim();
            if (!line || line.startsWith('//')) return;
            const where = `${file}:${lineNo + 1}`;
            if (line.startsWith('@')) {
                const [id, code, title, description] = line.slice(1).split('|').map((s) => s.trim());
                if (!id || !code || !title) throw new Error(`Bad course header at ${where}`);
                course = { id, code, title, description: description || '', units: [], source: file };
                courses.push(course);
                unit = null;
            } else if (line.startsWith('#')) {
                if (!course) throw new Error(`Unit outside course at ${where}`);
                unit = { title: line.slice(1).trim(), topics: [] };
                course.units.push(unit);
            } else if (line.startsWith('-')) {
                if (!unit) throw new Error(`Topic outside unit at ${where}`);
                const parts = line.slice(1).split('|').map((s) => s.trim()).filter(Boolean);
                const [title, overview, ...termParts] = parts;
                const terms = termParts.map((p) => {
                    const idx = p.indexOf(' = ');
                    if (idx === -1) throw new Error(`Term without " = " at ${where}: ${p}`);
                    return { term: p.slice(0, idx).trim(), def: p.slice(idx + 3).trim() };
                });
                if (!title || !overview || terms.length < 2) throw new Error(`Topic needs title, overview and >=2 terms at ${where}`);
                unit.topics.push({ title, overview, terms });
            } else {
                throw new Error(`Unrecognised line at ${where}: ${line}`);
            }
        });
    });
    return courses;
}

// ---------------------------------------------------------------- helpers
function esc(text) {
    return String(text)
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

function mermaidLabel(text) {
    return String(text)
        .replace(/["`]/g, "'")
        .replace(/[[\]{}()<>|;#]/g, ' ')
        .replace(/&/g, 'and')
        .replace(/\s+/g, ' ')
        .trim()
        .slice(0, 60);
}

// small deterministic PRNG so rebuilding gives identical files (clean git diffs)
function seededRandom(seedText) {
    let h = 2166136261;
    for (let i = 0; i < seedText.length; i += 1) {
        h ^= seedText.charCodeAt(i);
        h = Math.imul(h, 16777619);
    }
    return () => {
        h += 0x6d2b79f5;
        let t = h;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

function shuffle(list, rand) {
    const out = [...list];
    for (let i = out.length - 1; i > 0; i -= 1) {
        const j = Math.floor(rand() * (i + 1));
        [out[i], out[j]] = [out[j], out[i]];
    }
    return out;
}

function pickDistractors(pool, exclude, count, rand) {
    const seen = new Set([exclude.toLowerCase()]);
    const picked = [];
    shuffle(pool, rand).forEach((item) => {
        const key = item.toLowerCase();
        if (picked.length < count && !seen.has(key)) {
            seen.add(key);
            picked.push(item);
        }
    });
    return picked;
}

const ACCENTS = ['#3b82f6', '#10b981', '#f59e0b', '#8b5cf6', '#ec4899', '#06b6d4'];

// ---------------------------------------------------------------- content builders
function buildTopicHtml(course, unit, unitNumber, topic, topicIndex) {
    const terms = topic.terms;
    const half = Math.ceil(terms.length / 2);
    const left = terms.slice(0, half);
    const right = terms.slice(half);
    const li = (t) => `<li><strong>${esc(t.term)}:</strong> ${esc(t.def)}</li>`;

    const nodeLines = terms.map((t, i) => `    T --> N${i}[${mermaidLabel(t.term)}]`);
    const styleLines = [
        '    style T fill:#1e293b,stroke:#3b82f6,color:#fff',
        ...terms.map((_, i) => `    style N${i} fill:#1e293b,stroke:${ACCENTS[(i + 1) % ACCENTS.length]},color:#fff`)
    ];
    const prevTopic = unit.topics[topicIndex - 1];
    const nextTopic = unit.topics[topicIndex + 1];
    const flowLines = [];
    if (prevTopic) flowLines.push(`    P[Prev: ${mermaidLabel(prevTopic.title)}] -.-> T`);
    if (nextTopic) flowLines.push(`    T -.-> X[Next: ${mermaidLabel(nextTopic.title)}]`);

    const shortQs = terms.slice(0, 3).map((t) => `<li>Define <em>${esc(t.term)}</em> and state where it is used. <span class="text-slate-500">(2-3 marks)</span></li>`).join('\n            ');
    const longQ = `Explain <em>${esc(topic.title)}</em> with a neat labelled diagram, covering ${terms.slice(0, 3).map((t) => esc(t.term)).join(', ')}. <span class="text-slate-500">(7 marks)</span>`;
    const compareQ = terms.length >= 2
        ? `<li>Differentiate between <em>${esc(terms[0].term)}</em> and <em>${esc(terms[1].term)}</em> (any four points). <span class="text-slate-500">(4 marks)</span></li>`
        : '';

    const tableRows = terms.map((t) => `<tr class="border-t border-slate-800"><td class="py-2 pr-4 font-semibold text-cyan-300 align-top">${esc(t.term)}</td><td class="py-2 text-slate-300">${esc(t.def)}</td></tr>`).join('\n            ');

    const lowerFirst = (text) => text.charAt(0).toLowerCase() + text.slice(1);
    const explain = terms.map((t, i) => {
        const lead = i === 0 ? 'Start with' : (i === terms.length - 1 ? 'Finally, there is' : 'Next comes');
        return `${lead} <strong>${esc(t.term)}</strong>, which is ${esc(lowerFirst(t.def.replace(/[.;]\s*$/, '')))}.`;
    }).join(' ');
    const neighbours = unit.topics.filter((_, i) => i !== topicIndex).map((t) => esc(t.title));
    const paths = resourcePaths(course.id);
    const refs = (REFERENCES[course.id] || []).map(([title, author]) => `<li><em>${esc(title)}</em> &mdash; ${esc(author)}</li>`).join('\n            ');
    const videos = [
        [`${topic.title} ${course.title}`, `${topic.title} &mdash; full lecture`],
        [`${topic.title} NPTEL`, `${topic.title} &mdash; NPTEL / IIT lectures`],
        [`${topic.title} RGPV ${course.code} important questions`, `${course.code} &mdash; RGPV exam-oriented explanation`],
        [`${course.title} unit ${unitNumber} ${unit.title}`, `Unit ${unitNumber} complete playlist: ${esc(unit.title)}`]
    ].map(([q, label]) => `<li><a href="${ytSearch(q)}" target="_blank" rel="noopener" class="text-red-300 hover:text-red-200 underline decoration-red-500/40">&#9654; ${label}</a></li>`).join('\n            ');

    const deep = `<h3 class="text-xl font-bold mb-2 text-blue-400">In-depth Explanation</h3>
<div class="bg-slate-900/70 border border-slate-700 rounded-xl p-5 mb-6 text-sm text-slate-300 leading-relaxed space-y-3">
    <p>${esc(topic.overview)} ${explain}</p>
    <p>Together, ${joinList(terms.map((t) => `<em>${esc(t.term)}</em>`))} form the vocabulary examiners expect when they ask about <strong>${esc(topic.title)}</strong>. Write each definition precisely, add a labelled diagram or formula where one exists, and close with an application or example.</p>
    ${neighbours.length ? `<p><strong>Links within Unit ${unitNumber}:</strong> this topic is usually read together with ${joinList(neighbours)}; long answers on <em>${esc(unit.title)}</em> often combine them.</p>` : ''}
</div>`;

    const study = `<div class="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
    <div class="bg-gray-800/90 p-5 rounded-xl border-t-4 border-red-500 shadow-lg">
        <h4 class="text-red-300 font-bold mb-3 text-lg">&#127909; Video Lectures</h4>
        <ul class="space-y-2 text-sm">
            ${videos}
        </ul>
    </div>
    <div class="bg-gray-800/90 p-5 rounded-xl border-t-4 border-cyan-500 shadow-lg">
        <h4 class="text-cyan-300 font-bold mb-3 text-lg">&#128218; Study Material &amp; References</h4>
        <ul class="space-y-1.5 text-sm text-gray-300">
            <li><a href="${paths.notesPdf}" target="_blank" rel="noopener" download class="text-cyan-300 underline">&#11015; ${esc(course.code)} unit-wise study notes (PDF)</a></li>
            <li><a href="${paths.paperPdf}" target="_blank" rel="noopener" download class="text-cyan-300 underline">&#11015; ${esc(course.code)} RGPV model question paper (PDF)</a></li>
            <li><a href="${RGPV_PORTAL}" target="_blank" rel="noopener" class="text-cyan-300 underline">Official RGPV scheme &amp; syllabus portal</a></li>
        </ul>
        ${refs ? `<p class="text-xs uppercase tracking-wider text-slate-500 mt-3 mb-1">Standard textbooks</p>
        <ul class="list-disc pl-5 space-y-1 text-xs text-gray-400">
            ${refs}
        </ul>` : ''}
    </div>
</div>`;

    return `<h3 class="text-2xl font-bold mb-4 text-blue-400">${esc(topic.title)}</h3>
<p class="mb-2 text-xs uppercase tracking-wider text-slate-500">${esc(course.code)} &bull; Unit ${unitNumber}: ${esc(unit.title)}</p>
<p class="mb-4 text-slate-300 leading-relaxed">${esc(topic.overview)}</p>

<div class="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
    <div class="bg-gray-800/90 p-5 rounded-xl border-t-4 border-blue-500 shadow-lg">
        <h4 class="text-blue-300 font-bold mb-3 text-lg">Core Concepts</h4>
        <ul class="list-disc pl-5 space-y-2 text-gray-300 text-sm">
            ${left.map(li).join('\n            ')}
        </ul>
    </div>
    <div class="bg-gray-800/90 p-5 rounded-xl border-t-4 border-emerald-500 shadow-lg">
        <h4 class="text-emerald-300 font-bold mb-3 text-lg">Key Points &amp; Exam Focus</h4>
        <ul class="list-disc pl-5 space-y-2 text-gray-300 text-sm">
            ${(right.length ? right : left.slice(-1)).map(li).join('\n            ')}
        </ul>
    </div>
</div>

<h3 class="text-xl font-bold mb-2 text-blue-400">Concept Map</h3>
<div class="mermaid bg-gray-900 p-6 rounded-lg mb-6 flex justify-center border border-gray-700 shadow-inner">
graph LR
    T[${mermaidLabel(topic.title)}]
${nodeLines.join('\n')}
${flowLines.join('\n')}
${styleLines.join('\n')}
</div>

<h3 class="text-xl font-bold mb-2 text-blue-400">Quick Revision Table</h3>
<div class="overflow-x-auto mb-6">
    <table class="w-full text-sm">
        <tbody>
            ${tableRows}
        </tbody>
    </table>
</div>

${deep}

<div class="bg-slate-900 border border-amber-500/30 rounded-xl p-5 mb-6 text-sm text-amber-200/90">
    <h4 class="font-bold text-amber-300 mb-2 flex items-center gap-2">
        <span>&#128221;</span> RGPV Exam Blueprint
    </h4>
    <ul class="list-disc pl-5 space-y-1.5 leading-relaxed">
            ${shortQs}
            ${compareQ}
            <li>${longQ}</li>
    </ul>
</div>

${study}`;
}

function buildQuizzes(courseTerms, topic, seed) {
    const rand = seededRandom(seed);
    const allDefs = courseTerms.map((t) => t.def);
    const allTerms = courseTerms.map((t) => t.term);
    const quizzes = [];
    const chosen = shuffle(topic.terms, rand).slice(0, Math.min(3, topic.terms.length));

    chosen.forEach((t, idx) => {
        const reverse = idx % 2 === 1;
        const correct = reverse ? t.term : t.def;
        const distractors = pickDistractors(reverse ? allTerms : allDefs, correct, 3, rand);
        if (distractors.length < 3) return;
        const options = shuffle([correct, ...distractors], rand);
        quizzes.push({
            question: reverse
                ? `Which term matches this description: "${t.def}"?`
                : `Which statement correctly describes "${t.term}" (${topic.title})?`,
            options,
            answer: options.indexOf(correct),
            explanation: `${t.term}: ${t.def}`
        });
    });
    return quizzes;
}

function unitIdFor(courseId, n) {
    return `${courseId}-u${n}`;
}

function topicIdFor(courseId, n, m) {
    return `${courseId}-u${n}t${m}`;
}

function buildCourseFile(course) {
    const courseTerms = course.units.flatMap((u) => u.topics.flatMap((t) => t.terms));
    const details = {};
    course.units.forEach((unit, ui) => {
        const n = ui + 1;
        const unitKey = unitIdFor(course.id, n);
        details[unitKey] = {};
        unit.topics.forEach((topic, ti) => {
            const topicKey = topicIdFor(course.id, n, ti + 1);
            details[unitKey][topicKey] = {
                title: topic.title,
                content: buildTopicHtml(course, unit, n, topic, ti),
                quizzes: buildQuizzes(courseTerms, topic, topicKey)
            };
        });
    });
    return `/**
 * Academy LMS - Generated Curriculum Data
 * Course: ${course.code} ${course.title}
 * Source: scripts/curriculum/${course.source} (rebuild with: node scripts/build_multibranch_curriculum.js)
 */
window.topicDetails = window.topicDetails || {};
Object.assign(window.topicDetails, ${JSON.stringify(details, null, 4)});
`;
}

function buildCourseEntry(course, primarySemester) {
    return {
        id: course.id,
        semester: primarySemester,
        title: course.title,
        code: course.code,
        description: course.description,
        generated: true,
        references: (REFERENCES[course.id] || []).map(([title, author]) => ({ title, author })),
        resources: resourcePaths(course.id),
        units: course.units.map((unit, ui) => ({
            id: unitIdFor(course.id, ui + 1),
            unitNumber: ui + 1,
            title: unit.title,
            topics: unit.topics.map((topic, ti) => ({ id: topicIdFor(course.id, ui + 1, ti + 1), title: topic.title }))
        }))
    };
}

// ---------------------------------------------------------------- main
function main() {
    const courses = parseSources();
    const byId = new Map();
    courses.forEach((c) => {
        if (byId.has(c.id)) throw new Error(`Duplicate course id ${c.id}`);
        byId.set(c.id, c);
    });

    const dataSrc = fs.readFileSync(DATA_FILE, 'utf8');
    const baseSrc = dataSrc.includes(START_MARK) ? dataSrc.slice(0, dataSrc.indexOf(START_MARK)).trimEnd() : dataSrc.trimEnd();
    const existingIds = new Set([...baseSrc.matchAll(/^\s{8}id: '([^']+)',\s*$/gm)].map((m) => m[1]));

    // validate plan + find each new course's first semester (used as its primary semester)
    const primarySem = {};
    const problems = [];
    Object.entries(PLAN).forEach(([branch, sems]) => {
        if (!BRANCHES[branch]) problems.push(`Plan uses unknown branch ${branch}`);
        Object.entries(sems).forEach(([sem, entries]) => {
            entries.forEach(({ id }) => {
                if (!byId.has(id) && !existingIds.has(id)) problems.push(`${branch} sem ${sem}: unknown course ${id}`);
                if (byId.has(id)) primarySem[id] = Math.min(primarySem[id] || 99, Number(sem));
            });
        });
    });
    courses.forEach((c) => {
        if (!primarySem[c.id]) problems.push(`Course ${c.id} is not used by any branch plan`);
    });
    if (problems.length) {
        console.error(problems.join('\n'));
        process.exit(1);
    }

    let topicCount = 0;
    let quizCount = 0;
    courses.forEach((course) => {
        const fileSrc = buildCourseFile(course);
        fs.writeFileSync(path.join(JS_DIR, `data_${course.id}.js`), fileSrc);
        course.units.forEach((u) => { topicCount += u.topics.length; });
        quizCount += (fileSrc.match(/"question":/g) || []).length;
    });

    const entries = courses.map((c) => buildCourseEntry(c, primarySem[c.id]));
    const block = `${START_MARK}
coursesData.push(...${JSON.stringify(entries, null, 4)});
window.BRANCHES = ${JSON.stringify(BRANCHES, null, 4)};
window.branchPlan = ${JSON.stringify(PLAN, null, 4)};
${END_MARK}
`;
    fs.writeFileSync(DATA_FILE, `${baseSrc}\n\n${block}`);
    console.log(`Generated ${courses.length} subjects, ${topicCount} topics, ${quizCount} MCQs.`);
}

if (require.main === module) main();

module.exports = { parseSources, resourcePaths, ytSearch, REFERENCES };
